const nodes = [
  ...document.querySelectorAll(
    "[data-i18n], [data-i18n-alt], [data-i18n-aria], [data-i18n-title]",
  ),
];
const vi = {
  pauseMotion: "Tạm dừng chuyển động",
  resumeMotion: "Tiếp tục chuyển động",
};
for (const node of nodes) {
  if (node.dataset.i18n) vi[node.dataset.i18n] = node.textContent.trim();
  if (node.dataset.i18nAlt) vi[node.dataset.i18nAlt] = node.getAttribute("alt");
  if (node.dataset.i18nAria)
    vi[node.dataset.i18nAria] = node.getAttribute("aria-label");
  if (node.dataset.i18nTitle)
    vi[node.dataset.i18nTitle] = node.getAttribute("title");
}
// Preserve explicit BRs, without treating source formatting as visual line breaks.
for (const node of nodes.filter(
  (node) => node.dataset.i18n && node.querySelector("br"),
)) {
  vi[node.dataset.i18n] = [...node.childNodes]
    .map((child) => (child.nodeName === "BR" ? "\u0000" : child.textContent))
    .join("")
    .split("\u0000")
    .map((line) => line.replace(/\s+/g, " ").trim())
    .join("\n");
}
